
/// <reference types="vite/client" />

declare module "*.css" {
  const css: string;
  export default css;
}

declare module "*.scss" {
  const scss: string;
  export default scss;
}

declare module "*.svg" {
  const src: string;
  export default src;
}

declare module "*.png" {
  const src: string;
  export default src;
}

declare module "*.webp" {
  const src: string;
  export default src;
}

declare module "*.glb" {
  const src: string;
  export default src;
}

declare module "*.hdr" {
  const src: string;
  export default src;
}
